import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import '../../../../Config/Cubit/settings_cubit.dart';class LanguageList extends StatelessWidget {  const LanguageList({super.key});  @override  Widget build(BuildContext context) {    return Column(      crossAxisAlignment: CrossAxisAlignment.start,      children: _buildLanguageItems(          context, context.read<SettingsCubit>().state.locale),    );  }  List<Widget> _buildLanguageItems(      BuildContext context, Locale selectedLocale) {    final languages = [      {        'locale': const Locale(          'ar',        ),        'name': 'Arabic'      },      {        'locale': const Locale(          'en',        ),        'name': 'English'      },    ];    return List.generate(languages.length, (index) {      final lang = languages[index];      bool isSelected = lang['locale'] == selectedLocale;      return Column(        children: [          InkWell(            onTap: () {              context                  .read<SettingsCubit>()                  .changeLanguage(lang['locale'] as Locale);            },            child: Padding(              padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),              child: Row(                mainAxisAlignment: MainAxisAlignment.spaceBetween,                children: [                  Text(lang['name'] as String,                      style: const TextStyle(fontSize: 16)),                  if (isSelected) const Icon(Icons.check, color: Colors.brown),                  // ✅ علامة الصح                ],              ),            ),          ),          if (index != languages.length - 1)            Divider(color: Colors.grey.shade300),        ],      );    });  }}